  created: function created() {},
  mounted: function mounted() {
    this.menuStyle = this.$store.state.admin.userTemplateConfig.menu.style;
  },
  methods: {
    linkUrl: function linkUrl(e) {
      this.menuData.list[this.activeIndex].url = e;
