    addHotTxt: function addHotTxt() {
      this.menuData.list.push({
        pic: "",
        name: "",
        url: ""
      });
    },
    // 点击图文封面
    modalPicTap: function modalPicTap(title, index) {
      this.activeIndex = index;
      this.modalPic = true;
    },
    getLink: function getLink(index) {
      this.activeIndex = index;
      this.$refs.linkaddres.modals = true;
    },
    // 获取图片信息
    getPic: function getPic(pc) {
      var _this = this;
      this.$nextTick(function () {
        _this.menuData.list[_this.activeIndex].pic = pc.att_dir;
        _this.modalPic = false;
      });
    },
    selectStyle: function selectStyle(index) {
      this.menuStyle = index + 1;
    },
    saveStyle: function saveStyle() {
      this.menuData.style = this.menuStyle;
    },
    // 删除
    bindDelete: function bindDelete(item, index) {
      this.menuData.list.splice(index, 1);
    }
  }
};
